 try:p=Path(os.fsdecode(args[0])).resolve()
 except (TypeError,ValueError):return
 if inside(p,original):
  blocked.append(dict(event=event,path=str(p)));raise PermissionError('Original workspace access forbidden during standalone reproduction: '+str(p))
 if event=='open' and inside(p,checkout):
  mode=args[1] if len(args)>1 else None;flags=args[2] if len(args)>2 else 0
  writing=(isinstance(mode,str) and any(c in mode for c in 'wax+')) or (isinstance(flags,int) and bool(flags&(os.O_WRONLY|os.O_RDWR)))
  (writes if writing else (reads if p.is_file() else missing_read_probes)).add(str(p.relative_to(checkout)))
sys.addaudithook(hook)
