finally:
 record.write_text(json.dumps(dict(success=success,guard_self_test=guard_self_test,blocked_original_workspace_accesses=blocked,checkout_reads=sorted(reads),checkout_writes=sorted(writes),nonexistent_read_probes=sorted(missing_read_probes)),indent=2)+'\n')
